begin;

insert into public.permissions(code,description) values
 ('HOTEL_INQUIRY_READ','호텔 소유주 문의 조회'),
 ('HOTEL_INQUIRY_REPLY','호텔 소유주 문의 답변·내부메모'),
 ('HOTEL_INQUIRY_ASSIGN','호텔 소유주 문의 담당자 지정'),
 ('HOTEL_INQUIRY_SETTINGS','호텔 문의처·라우팅 설정'),
 ('HOTEL_OWNER_INQUIRY_READ','호텔 소유주 본인 호텔 문의 조회'),
 ('HOTEL_OWNER_INQUIRY_CREATE','호텔 소유주 본인 호텔 문의 작성·후속응답')
on conflict(code) do update set description=excluded.description;

create table public.hotel_inquiry_categories(
 company_id uuid not null references public.companies(id), code text not null check(code in ('CONTRACT_POLICY','SALES_SETTLEMENT','ROOM_FACILITY','INSPECTION_ISSUE','ACCOUNT_PERMISSION','OTHER')),
 name text not null check(char_length(btrim(name)) between 1 and 100), status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE')),
 version integer not null default 1 check(version>0), primary key(company_id,code)
);
create function public.hotel_inquiry_seed_categories_v1() returns trigger language plpgsql security definer set search_path=pg_catalog as $f$
begin
 insert into public.hotel_inquiry_categories(company_id,code,name) values
  (new.id,'CONTRACT_POLICY','계약·운영정책'),
  (new.id,'SALES_SETTLEMENT','매출·정산'),
  (new.id,'ROOM_FACILITY','객실·시설'),
  (new.id,'INSPECTION_ISSUE','객실점검·운영이슈'),
  (new.id,'ACCOUNT_PERMISSION','계정·권한'),
  (new.id,'OTHER','기타')
 on conflict do nothing;
 return new;
end $f$;
revoke all on function public.hotel_inquiry_seed_categories_v1() from public;
create trigger hotel_inquiry_seed_categories_after_company
 after insert on public.companies for each row
 execute function public.hotel_inquiry_seed_categories_v1();
insert into public.hotel_inquiry_categories(company_id,code,name)
select c.id,v.code,v.name from public.companies c cross join (values('CONTRACT_POLICY','계약·운영정책'),('SALES_SETTLEMENT','매출·정산'),('ROOM_FACILITY','객실·시설'),('INSPECTION_ISSUE','객실점검·운영이슈'),('ACCOUNT_PERMISSION','계정·권한'),('OTHER','기타'))v(code,name) on conflict do nothing;
create table public.hotel_inquiry_contacts(
 company_id uuid not null,branch_id uuid not null,phone text not null check(char_length(btrim(phone)) between 3 and 50),email text not null check(email~'^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),operating_hours text not null check(char_length(btrim(operating_hours)) between 2 and 500),version integer not null default 1 check(version>0),updated_by uuid not null,updated_at timestamptz not null default now(),primary key(company_id,branch_id),foreign key(company_id,branch_id) references public.hotel_profiles(company_id,branch_id),foreign key(company_id,updated_by) references public.users(company_id,id)
);
create table public.hotel_inquiries(
 id uuid primary key,company_id uuid not null,branch_id uuid not null,category_code text not null,category_name_snapshot text not null,title text not null check(char_length(btrim(title)) between 2 and 160),status text not null default 'RECEIVED' check(status in ('RECEIVED','ASSIGNED','ANSWERING','ANSWERED','SUPPLEMENT_REQUESTED','CLOSED')),version integer not null default 1 check(version>0),created_by uuid not null,routing_group_id uuid,assigned_user_id uuid,answered_at timestamptz,closed_at timestamptz,reopen_until timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(company_id,branch_id,id),foreign key(company_id,branch_id) references public.hotel_profiles(company_id,branch_id),foreign key(company_id,category_code) references public.hotel_inquiry_categories(company_id,code),foreign key(company_id,created_by) references public.users(company_id,id),foreign key(company_id,routing_group_id) references public.user_groups(company_id,id),foreign key(company_id,assigned_user_id) references public.users(company_id,id),check((status='CLOSED')=(closed_at is not null)),check((closed_at is null and reopen_until is null) or reopen_until=closed_at+interval '30 days')
);
create index hotel_inquiries_list_idx on public.hotel_inquiries(company_id,branch_id,status,updated_at desc,id);
create table public.hotel_inquiry_routes(company_id uuid not null,branch_id uuid not null,category_code text not null,group_id uuid,active boolean not null default true,version integer not null default 1 check(version>0),updated_by uuid not null,updated_at timestamptz not null default now(),primary key(company_id,branch_id,category_code),foreign key(company_id,branch_id) references public.hotel_profiles(company_id,branch_id),foreign key(company_id,category_code) references public.hotel_inquiry_categories(company_id,code),foreign key(company_id,group_id) references public.user_groups(company_id,id),foreign key(company_id,updated_by) references public.users(company_id,id));
create table public.hotel_inquiry_messages(id uuid primary key,company_id uuid not null,branch_id uuid not null,inquiry_id uuid not null,inquiry_version integer not null check(inquiry_version>0),visibility text not null check(visibility in ('PUBLIC','INTERNAL')),body text not null check(char_length(btrim(body)) between 2 and 4000),actor_user_id uuid not null,actor_display_name_snapshot text not null,created_at timestamptz not null default now(),unique(company_id,branch_id,id),foreign key(company_id,branch_id,inquiry_id) references public.hotel_inquiries(company_id,branch_id,id),foreign key(company_id,actor_user_id) references public.users(company_id,id));

