create table public.hotel_inquiry_message_attachments(id uuid primary key,company_id uuid not null,branch_id uuid not null,inquiry_id uuid not null,message_id uuid not null,file_version_id uuid not null,display_name_snapshot text not null check(char_length(btrim(display_name_snapshot)) between 1 and 180),created_at timestamptz not null default now(),unique(company_id,branch_id,message_id,file_version_id),foreign key(company_id,branch_id,inquiry_id) references public.hotel_inquiries(company_id,branch_id,id),foreign key(company_id,branch_id,message_id) references public.hotel_inquiry_messages(company_id,branch_id,id),foreign key(company_id,file_version_id) references public.hotel_file_versions(company_id,id));
create table public.hotel_inquiry_assignments(id uuid primary key,company_id uuid not null,branch_id uuid not null,inquiry_id uuid not null,inquiry_version integer not null check(inquiry_version>0),assignee_user_id uuid not null,reason text not null check(char_length(btrim(reason)) between 2 and 500),assigned_by uuid not null,assigned_at timestamptz not null default now(),unique(company_id,branch_id,inquiry_id,inquiry_version),foreign key(company_id,branch_id,inquiry_id) references public.hotel_inquiries(company_id,branch_id,id),foreign key(company_id,assignee_user_id) references public.users(company_id,id),foreign key(company_id,assigned_by) references public.users(company_id,id));
