create function public.hotel_inquiry_actor_v1(p_company_id uuid,p_branch_id uuid,p_session_token text,p_permission_code text)
returns table(session_id uuid,user_id uuid,user_type text,display_name text) language sql stable security definer set search_path=pg_catalog as $f$
with actor as(select s.id session_id,u.id user_id,u.user_type,u.display_name from public.auth_sessions s join public.users u on u.company_id=s.company_id and u.id=s.user_id join public.companies c on c.id=s.company_id where public.runtime_has_capability('API_RUNTIME') and p_session_token~'^[A-Za-z0-9_-]{43}$' and s.id=nullif(current_setting('app.session_id',true),'')::uuid and s.company_id=p_company_id and s.token_hash=sha256(convert_to(p_session_token,'UTF8')) and s.revoked_at is null and s.idle_expires_at>statement_timestamp() and s.absolute_expires_at>statement_timestamp() and u.status='ACTIVE' and c.status='ACTIVE'),subjects as(select 'USER'::text subject_type,a.user_id subject_id from actor a union all select 'ROLE',m.role_id from actor a join public.user_role_memberships m on m.company_id=p_company_id and m.user_id=a.user_id join public.roles r on r.company_id=m.company_id and r.id=m.role_id and r.status='ACTIVE' where m.valid_from<=statement_timestamp() and(m.valid_until is null or m.valid_until>statement_timestamp()) union all select 'GROUP',m.group_id from actor a join public.user_group_memberships m on m.company_id=p_company_id and m.user_id=a.user_id join public.user_groups g on g.company_id=m.company_id and g.id=m.group_id and g.status='ACTIVE' where m.valid_from<=statement_timestamp() and(m.valid_until is null or m.valid_until>statement_timestamp())),effects as(select pg.effect from public.permission_grants pg join subjects s on s.subject_type=pg.subject_type and s.subject_id=pg.subject_id where pg.company_id=p_company_id and pg.permission_code=p_permission_code and(pg.branch_id is null or pg.branch_id=p_branch_id) and pg.valid_from<=statement_timestamp() and(pg.valid_until is null or pg.valid_until>statement_timestamp()))
select a.* from actor a where not exists(select 1 from effects where effect='DENY') and exists(select 1 from effects where effect='ALLOW') and ((a.user_type='HOTEL_OWNER' and p_permission_code in('HOTEL_OWNER_INQUIRY_READ','HOTEL_OWNER_INQUIRY_CREATE')) or(a.user_type='INTERNAL_STAFF' and p_permission_code in('HOTEL_INQUIRY_READ','HOTEL_INQUIRY_REPLY','HOTEL_INQUIRY_ASSIGN','HOTEL_INQUIRY_SETTINGS'))) and case a.user_type when 'INTERNAL_STAFF' then exists(select 1 from public.hotel_staff_assignments x where x.company_id=p_company_id and x.branch_id=p_branch_id and x.user_id=a.user_id and x.terminated_at is null and x.start_date<=statement_timestamp()::date and(x.end_date is null or x.end_date>=statement_timestamp()::date)) when 'HOTEL_OWNER' then exists(select 1 from public.hotel_owner_assignments x where x.company_id=p_company_id and x.branch_id=p_branch_id and x.user_id=a.user_id and x.terminated_at is null and x.start_date<=statement_timestamp()::date and(x.end_date is null or x.end_date>=statement_timestamp()::date)) else false end
$f$;
revoke all on function public.hotel_inquiry_actor_v1(uuid,uuid,text,text) from public;

create function public.hotel_inquiry_snapshot_v1(p_company_id uuid,p_branch_id uuid,p_inquiry_id uuid,p_internal boolean) returns jsonb language sql stable security invoker set search_path=pg_catalog as $f$
select jsonb_build_object('id',i.id,'hotelId',i.branch_id,'categoryCode',i.category_code,'categoryName',i.category_name_snapshot,'title',i.title,'status',i.status,'version',i.version,'assignee',case when au.id is null then null when p_internal then jsonb_build_object('userId',au.id,'displayName',au.display_name) else jsonb_build_object('displayName',au.display_name) end,'messages',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'body',m.body,'visibility',m.visibility,'actor',case when p_internal then jsonb_build_object('userId',m.actor_user_id,'displayName',m.actor_display_name_snapshot) else jsonb_build_object('displayName',m.actor_display_name_snapshot) end,'createdAt',to_char(m.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'attachments',coalesce((select jsonb_agg(jsonb_build_object('fileVersionId',a.file_version_id,'displayName',a.display_name_snapshot)order by a.created_at,a.id)from public.hotel_inquiry_message_attachments a where a.company_id=m.company_id and a.branch_id=m.branch_id and a.message_id=m.id),'[]'::jsonb)) order by m.created_at,m.id) from public.hotel_inquiry_messages m where m.company_id=i.company_id and m.branch_id=i.branch_id and m.inquiry_id=i.id and(p_internal or m.visibility='PUBLIC')),'[]'::jsonb),'answeredAt',case when i.answered_at is null then null else to_char(i.answered_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') end,'closedAt',case when i.closed_at is null then null else to_char(i.closed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') end,'reopenUntil',case when i.reopen_until is null then null else to_char(i.reopen_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') end,'createdAt',to_char(i.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'updatedAt',to_char(i.updated_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))||case when p_internal then jsonb_build_object('statusHistory',coalesce((select jsonb_agg(jsonb_build_object('id',h.id,'action',h.action,'fromStatus',h.from_status,'toStatus',h.to_status,'reason',h.reason,'actor',case when h.actor_user_id is null then jsonb_build_object('displayName',h.actor_display_name_snapshot) else jsonb_build_object('userId',h.actor_user_id,'displayName',h.actor_display_name_snapshot) end,'createdAt',to_char(h.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'version',h.inquiry_version) order by h.inquiry_version) from public.hotel_inquiry_status_history h where h.company_id=i.company_id and h.branch_id=i.branch_id and h.inquiry_id=i.id),'[]'::jsonb)) else '{}'::jsonb end from public.hotel_inquiries i left join public.users au on au.company_id=i.company_id and au.id=i.assigned_user_id where i.company_id=p_company_id and i.branch_id=p_branch_id and i.id=p_inquiry_id
$f$;
revoke all on function public.hotel_inquiry_snapshot_v1(uuid,uuid,uuid,boolean) from public;

create function public.hotel_inquiry_owner_can_read_v1(p_company_id uuid,p_branch_id uuid,p_inquiry_id uuid,p_actor_user_id uuid) returns boolean language sql stable security invoker set search_path=pg_catalog as $f$
 select exists(
  select 1 from public.hotel_inquiries i
  where i.company_id=p_company_id and i.branch_id=p_branch_id and i.id=p_inquiry_id
   and(
    i.created_by=p_actor_user_id
    or(
      exists(
        select 1 from public.hotel_owner_assignments owner_history
        where owner_history.company_id=i.company_id
         and owner_history.branch_id=i.branch_id
         and owner_history.user_id=i.created_by
      )
      and not exists(
      select 1 from public.hotel_owner_assignments owner_assignment
      where owner_assignment.company_id=i.company_id
       and owner_assignment.branch_id=i.branch_id
       and owner_assignment.user_id=i.created_by
       and owner_assignment.terminated_at is null
       and owner_assignment.start_date<=statement_timestamp()::date
       and(owner_assignment.end_date is null or owner_assignment.end_date>=statement_timestamp()::date)
    )
   )
  )
 )
$f$;
revoke all on function public.hotel_inquiry_owner_can_read_v1(uuid,uuid,uuid,uuid) from public;

create function public.hotel_inquiry_settings_snapshot_v1(p_company_id uuid,p_branch_id uuid)returns jsonb language sql stable set search_path=pg_catalog as $f$
select jsonb_build_object('contact',(select jsonb_build_object('phone',c.phone,'email',c.email,'operatingHours',c.operating_hours,'version',c.version)from public.hotel_inquiry_contacts c where c.company_id=p_company_id and c.branch_id=p_branch_id),'routes',coalesce((select jsonb_agg(jsonb_build_object('categoryCode',cat.code,'categoryName',cat.name,'groupId',r.group_id,'groupName',g.name,'active',coalesce(r.active,false),'version',coalesce(r.version,0))order by cat.name,cat.code)from public.hotel_inquiry_categories cat left join public.hotel_inquiry_routes r on r.company_id=cat.company_id and r.branch_id=p_branch_id and r.category_code=cat.code left join public.user_groups g on g.company_id=r.company_id and g.id=r.group_id where cat.company_id=p_company_id and cat.status='ACTIVE'),'[]'::jsonb),'groups',coalesce((select jsonb_agg(jsonb_build_object('id',g.id,'name',g.name)order by g.name,g.id)from public.user_groups g where g.company_id=p_company_id and g.status='ACTIVE'),'[]'::jsonb))
$f$;
revoke all on function public.hotel_inquiry_settings_snapshot_v1(uuid,uuid) from public;

create function public.hotel_inquiry_idempotency_begin_v1(p_company_id uuid,p_actor_user_id uuid,p_idempotency_key text,p_http_method text,p_operation_path text,p_request_hash text)returns table(command_status text,result_snapshot jsonb)language plpgsql volatile set search_path=pg_catalog as $f$ declare existing record;now_at timestamptz:=statement_timestamp();begin if btrim(coalesce(p_idempotency_key,''))=''or p_http_method not in('POST','PUT','PATCH','DELETE')or btrim(coalesce(p_operation_path,''))=''or btrim(coalesce(p_request_hash,''))=''then return query select'VALIDATION_ERROR',null::jsonb;return;end if;perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_actor_user_id::text||':'||p_idempotency_key||':'||p_http_method||':'||p_operation_path,0));delete from public.idempotency_records where company_id=p_company_id and actor_user_id=p_actor_user_id and idempotency_key=p_idempotency_key and http_method=p_http_method and operation_path=p_operation_path and expires_at<=now_at;select record.request_hash,record.result_snapshot into existing from public.idempotency_records record where record.company_id=p_company_id and record.actor_user_id=p_actor_user_id and record.idempotency_key=p_idempotency_key and record.http_method=p_http_method and record.operation_path=p_operation_path and record.status='COMPLETED';if found then return query select case when existing.request_hash=p_request_hash then'REPLAYED'else'IDEMPOTENCY_CONFLICT'end,case when existing.request_hash=p_request_hash then existing.result_snapshot else null::jsonb end;end if;end $f$;
revoke all on function public.hotel_inquiry_idempotency_begin_v1(uuid,uuid,text,text,text,text) from public;

create function public.hotel_inquiry_capabilities_v1(p_company_id uuid,p_session_token text) returns table(command_status text,result_snapshot jsonb) language plpgsql volatile security definer set search_path=pg_catalog as $f$
begin return query with actor as(select s.id session_id,u.id user_id,u.user_type from public.auth_sessions s join public.users u on u.company_id=s.company_id and u.id=s.user_id where public.runtime_has_capability('API_RUNTIME') and p_session_token~'^[A-Za-z0-9_-]{43}$' and s.id=nullif(current_setting('app.session_id',true),'')::uuid and s.company_id=p_company_id and s.token_hash=sha256(convert_to(p_session_token,'UTF8')) and s.revoked_at is null and s.idle_expires_at>statement_timestamp() and s.absolute_expires_at>statement_timestamp() and u.status='ACTIVE'),scopes as(select h.branch_id,b.name,a.user_type from actor a join public.hotel_staff_assignments x on a.user_type='INTERNAL_STAFF' and x.company_id=p_company_id and x.user_id=a.user_id and x.terminated_at is null and x.start_date<=statement_timestamp()::date and(x.end_date is null or x.end_date>=statement_timestamp()::date) join public.hotel_profiles h on h.company_id=x.company_id and h.branch_id=x.branch_id join public.branches b on b.company_id=h.company_id and b.id=h.branch_id union select h.branch_id,b.name,a.user_type from actor a join public.hotel_owner_assignments x on a.user_type='HOTEL_OWNER' and x.company_id=p_company_id and x.user_id=a.user_id and x.terminated_at is null and x.start_date<=statement_timestamp()::date and(x.end_date is null or x.end_date>=statement_timestamp()::date) join public.hotel_profiles h on h.company_id=x.company_id and h.branch_id=x.branch_id join public.branches b on b.company_id=h.company_id and b.id=h.branch_id) select case when exists(select 1 from actor)then'OK'else'FORBIDDEN'end,case when exists(select 1 from actor)then jsonb_build_object('hotels',coalesce((select jsonb_agg(jsonb_build_object('hotelId',s.branch_id,'hotelName',s.name,'ownerView',s.user_type='HOTEL_OWNER','canRead',exists(select 1 from public.hotel_inquiry_actor_v1(p_company_id,s.branch_id,p_session_token,case when s.user_type='HOTEL_OWNER'then'HOTEL_OWNER_INQUIRY_READ'else'HOTEL_INQUIRY_READ'end)),'canCrea