create function public.hotel_inquiry_read_v1(p_company_id uuid,p_branch_id uuid,p_inquiry_id uuid,p_query jsonb,p_session_token text) returns table(command_status text,result_snapshot jsonb) language plpgsql volatile security definer set search_path=pg_catalog as $f$
