p_company_id and n.branch_id=p_branch_id and n.recipient_user_id=actor.user_id order by n.created_at desc,n.id limit 100)n join public.hotel_inquiries i on i.company_id=n.company_id and i.branch_id=n.branch_id and i.id=n.inquiry_id),'[]'::jsonb));exception when invalid_text_representation then return query select'NOT_FOUND',null::jsonb;end $f$;
