count;if hotel_count=80 then insert into public.audit_events(id,event_code,actor_user_id,actor_type,session_id,company_id,branch_id,resource_type,resource_id,after_summary,result,trace_id)values(p_alert_audit_event_id,'HOTEL_FILE_BULK_EXPORT_ALERT',a.user_id,a.user_type,a.session_id,p_company_id,p_branch_id,'HOTEL_FILE_ACCESS_WINDOW',p_branch_id,jsonb_build_object('windowStartedAt',window_at,'requestCount',80),'SUCCEEDED',p_trace_id);end if;if hotel_count is null then insert into public.audit_events(id,event_code,actor_user_id,actor_type,session_id,company_id,branch_id,resource_type,resource_id,after_summary,result,trace_id)values(p_audit_event_id,'HOTEL_INQUIRY_FILE_VIEW_RATE_LIMITED',a.user_id,a.user_type,a.session_id,p_company_id,p_branch_id,'HOTEL_FILE_VERSION',p_file_version_id,jsonb_build_object('inquiryId',p_inquiry_id),'DENIED',p_trace_id);return query select'RATE_LIMITED',null::jsonb;return;end if;insert into public.hotel_file_access_grants(id,company_id,branch_id,actor_user_id,actor_type,session_id,inquiry_id,file_version_id,completion_token_hash,status,trace_id)values(p_grant_id,p_company_id,p_branch_id,a.user_id,a.user_type,a.session_id,p_inquiry_id,p_file_version_id,sha256(convert_to(p_completion_token,'UTF8')),'STARTED',p_trace_id);return query select'OK',jsonb_build_object('grantId',p_grant_id,'cleanObjectKey',f.clean_object_key,'etag',f.clean_etag,'objectVersion',f.clean_object_version,'sha256',f.clean_sha256,'sizeBytes',f.clean_size,'mimeType',f.detected_mime,'displayName',f.display_name);end $f$;
