create function public.hotel_inquiry_auto_close_v1(p_limit integer default 100) returns table(closed_count integer) language plpgsql volatile security definer set search_path=pg_catalog as $f$ declare n integer:=0;r record;begin if not public.runtime_has_capability('RECONCILER')then raise exception'forbidden'using errcode='42501';end if;for r in select*from public.hotel_inquiries where status='ANSWERED'and answered_at<=statement_timestamp()-interval'7 days'order by answered_at,id for update skip locked limit least(greatest(p_limit,1),1000)loop update public.hotel_inquiries set status='CLOSED',closed_at=statement_timestamp(),reopen_until=statement_timestamp()+interval'30 days',version=version+1,updated_at=statement_timestamp()where id=r.id;insert into public.hotel_inquiry_status_history(id,company_id,branch_id,inquiry_id,inquiry_version,action,from_status,to_status,reason,actor_user_id,actor_display_name_snapshot)values(gen_random_uuid(),r.company_id,r.branch_id,r.id,r.version+1,'AUTO_CLOSE','ANSWERED','CLOSED','답변완료 후 7일 무응답 자동종료',null,'시스템');insert into public.audit_events(id,event_code,actor_user_id,actor_type,session_id,company_id,branch_id,resource_type,resource_id,before_summary,after_summary,reason,result,trace_id)values(gen_random_uuid(),'HOTEL_INQUIRY_AUTO_CLOSE',null,'SYSTEM',null,r.company_id,r.branch_id,'HOTEL_INQUIRY',r.id,jsonb_build_object('status','ANSWERED','version',r.version),jsonb_build_object('status','CLOSED','version',r.version+1),'답변완료 후 7일 무응답 자동종료','SUCCEEDED',gen_random_uuid());insert into public.hotel_inquiry_notifications(id,company_id,branch_id,inquiry_id,inquiry_version,recipient_user_id,event_code)select gen_random_uuid(),r.company_id,r.branch_id,r.id,r.version+1,target.user_id,'HOTEL_INQUIRY_AUTO_CLOSE'from(select r.created_by user_id where exists(select 1 from public.users creator where creator.company_id=r.company_id and creator.id=r.created_by and creator.status='ACTIVE')and exists(select 1 from public.hotel_owner_assignments oa where oa.company_id=r.company_id and oa.branch_id=r.branch_id and oa.user_id=r.created_by and oa.terminated_at is null and oa.start_date<=statement_timestamp()::date and(oa.end_date is null or oa.end_date>=statement_timestamp()::date))union select oa.user_id from public.hotel_owner_assignments oa join public.users owner_user on owner_user.company_id=oa.company_id and owner_user.id=oa.user_id and owner_user.status='ACTIVE'where oa.company_id=r.company_id and oa.branch_id=r.branch_id and oa.terminated_at is null and oa.start_date<=statement_timestamp()::date and(oa.end_date is null or oa.end_date>=statement_timestamp()::date)and not exists(select 1 from public.hotel_owner_assignments creator_assignment where creator_assignment.company_id=r.company_id and creator_assignment.branch_id=r.branch_id and creator_assignment.user_id=r.created_by and creator_assignment.terminated_at is null and creator_assignment.start_date<=statement_timestamp()::date and(creator_assignment.end_date is null or creator_assignment.end_date>=statement_timestamp()::date))union select r.assigned_user_id where r.assigned_user_id is not null and exists(select 1 from public.users assignee where assignee.company_id=r.company_id and assignee.id=r.assigned_user_id and assignee.status='ACTIVE'))target on conflict do nothing;n:=n+1;end loop;return query select n;end $f$;
revoke all on function public.hotel_inquiry_auto_close_v1(integer) from public;

create function public.hotel_inquiry_rls_company_guard_v1(p_company_id uuid) returns boolean language sql stable security invoker set search_path=pg_catalog as $f$
 select case
  when public.runtime_is_schema_owner() then true
  when current_user='werehere_auth_session_definer' then true
  when current_user='werehere_tenant_authority_definer' then true
  when public.runtime_has_capability('API_RUNTIME') then p_company_id=public.api_current_company_id()
  when public.runtime_has_capability('RECONCILER') then p_company_id=public.reconciler_current_company_id()
  else false
 end
$f$;
revoke all on function public.hotel_inquiry_rls_company_guard_v1(uuid) from public;

do $rls$ declare t text;begin foreach t in array array['hotel_inquiry_categories','hotel_inquiry_contacts','hotel_inquiries','hotel_inquiry_routes','hotel_inquiry_messages','hotel_inquiry_message_attachments','hotel_inquiry_assignments','hotel_inquiry_status_history','hotel_inquiry_notifications']loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy %I_company_isolation on public.%I using(public.hotel_inquiry_rls_company_guard_v1(company_id))with check(public.hotel_inquiry_rls_company_guard_v1(company_id))',t,t);end loop;end $rls$;
do $acl$ declare r text;begin for r in select role_name from public.runtime_database_capabilities where capability='API_RUNTIME'loop execute format('revoke all on public.hotel_inquiry_categories,public.hotel_inquiry_contacts,public.hotel_inquiries,public.hotel_inquiry_routes,public.hotel_inquiry_messages,public.hotel_inquiry_message_attachments,public.hotel_inquiry_assignments,public.hotel_inquiry_status_history,public.hotel_inquiry_notifications from %I',r);execute format('grant execute on function public.hotel_inquiry_capabilities_v1(uuid,text)to %I',r);execute format('grant execute on function public.hotel_inquiry_read_v1(uuid,uuid,uuid,jsonb,text)to %I',r);execute format('grant execute on function public.hotel_inquiry_command_v1(uuid,uuid,uuid,text,integer,jsonb,text,uuid,text,text,text,text,uuid,uuid)to %I',r);execute format('grant execute on function public.hotel_inquiry_file_scope_v1(uuid,uuid,text)to %I',r);execute format('grant execute on function public.hotel_inquiry_file_command_v1(uuid,uuid,uuid,text,integer,jsonb,text,uuid,text,text,text,text,uuid,uuid)to %I',r);execute format('grant execute on function public.hotel_inquiry_file_view_v1(uuid,uuid,uuid,uuid,text,text,uuid,text,uuid,uuid,uuid)to %I',r);end loop;for r in select role_name from public.runtime_database_capabilities where capability='RECONCILER'loop execute format('grant execute on function public.hotel_inquiry_auto_close_v1(integer)to %I',r);end loop;end $acl$;
